// tickets.js — the 27 exam tickets. Shared by exam-tickets.html and drill.html.
// Shape: {n, tag, sec, core:[ids], ru:{topic, qs[3], a[{q,t}x3], kill}, en:{...}}
window.TICKETS = [
{n:1,tag:"Core-40 #17",sec:"llm",core:[17],
 ru:{topic:"Токены",
  qs:["Что такое токен? Дай определение так, как сказал бы интервьюеру.",
      "Сколько символов и сколько слов примерно в одном токене? Почему это среднее, а не правило?",
      "Почему русский текст стоит дороже английского? Механизм, а не факт."],
  a:[{q:"Определение",t:"Токен — это subword unit, кусок текста из фиксированного словаря модели, обычно на пятьдесят–двести тысяч записей. Модель не видит ни слов, ни букв: она видит целые числа, каждое из которых — индекс в этом словаре. И важно, что токены есть с обеих сторон — твой промпт токенизируется на входе, и модель порождает токены на выходе."},
     {q:"Цифры",t:"Примерно четыре символа английского, или три четверти слова. Это одна и та же величина в двух единицах, поэтому выбираешь одну и держишься её. А среднее это потому, что словарь строил алгоритм BPE: самые частые соседние пары склеивались в отдельные записи, поэтому частые слова стали одним токеном, а редкие режутся на куски. Длину определяет частота, а не смысл."},
     {q:"Кириллица",t:"Словарь строился на корпусе, где преобладал английский, поэтому эффективные склейки достались именно ему. Кириллица режется гораздо мельче — примерно один-два символа на токен вместо четырёх, то есть в два-четыре раза больше токенов на тот же смысл. И это не курьёз, а продуктовое решение: русскоязычная фича может стоить втрое дороже английской и втрое быстрее съедать контекстное окно."}],
  kill:"<b>«Token is a symbol»</b> — русское «символ» это character, английское symbol значит другое. Говори <b>subword unit</b>. И не путай «4 символа» с «4 слова» — это ошибка в пять раз."},
 en:{topic:"Tokens",
  qs:["What is a token? Define it the way you would to an interviewer.",
      "Roughly how many characters and how many words per token? Why is that an average, not a rule?",
      "Why does Russian text cost more than English? Give the mechanism, not the fact."],
  a:[{q:"Definition",t:"A token is a subword unit — a chunk of text from the model's fixed vocabulary, usually somewhere between fifty and two hundred thousand entries. The model never sees words or characters. It sees integers, each one an index into that vocabulary. And it matters that tokens exist on both sides: your prompt is tokenised on the way in, and the model produces tokens on the way out."},
     {q:"The numbers",t:"About four characters of English, or roughly three quarters of a word. Those are the same fact in two different units, so you pick one and stay with it. It's an average rather than a rule because the vocabulary was built by byte-pair encoding — the most frequent adjacent pairs got merged into single entries, so common words became one token and rare ones got split into pieces. Frequency decides length, not meaning."},
     {q:"Non-English",t:"The vocabulary was built on an English-heavy corpus, so English got the efficient merges. Cyrillic ends up split much finer — roughly one or two characters per token instead of four — which means two to four times more tokens for the same meaning. That's a product decision rather than trivia: a Russian-language feature can cost triple its English equivalent, and it eats the context window three times faster."}],
  kill:"<b>\"A token is a symbol\"</b> — Russian <i>символ</i> means <i>character</i>; English \"symbol\" doesn't. Say <b>subword unit</b>. And never say \"4 words per token\" — that's a 5x error."}},

{n:2,tag:"Core-40 #18",sec:"llm",core:[18],
 ru:{topic:"Контекстное окно",
  qs:["Что такое context window и что в него входит?",
      "Ты близко к лимиту и отправляешь запрос. Что произойдёт и в какой момент?",
      "Промпт 195k, окно 200k, max_tokens 8000. Результат? Почему?"],
  a:[{q:"Определение",t:"Контекстное окно — это максимум токенов, который модель обрабатывает за один запрос, причём вход и сгенерированный выход считаются вместе. За место в нём конкурирует всё сразу: системный промпт, история диалога, найденные документы, определения инструментов и результаты их вызовов. У Claude сейчас порядка двухсот тысяч, у GPT-4o сто двадцать восемь, у Gemini больше миллиона — но цифры двигаются, и перед собесом я бы их перепроверил."},
     {q:"Превышение",t:"Придёт ошибка invalid_request_error, и придёт она до начала генерации. Это ключевой момент: валидация происходит заранее, запрос отклоняется целиком, и ни одного токена не сгенерируется. Никакого мягкого усечения нет — модель не выбрасывает молча старые сообщения. Я это запоминаю как fail fast, not silent, и это хороший дизайн: молчаливое усечение дало бы неправильные ответы вообще без сигнала, а ошибку хотя бы можно обработать."},
     {q:"max_tokens",t:"Запрос будет отклонён. В окно должен поместиться вход плюс max_tokens, а не только вход — max_tokens это заявленный потолок ответа, и место под него резервируется заранее. Поэтому сто девяносто пять плюс восемь не влезают в двести, хотя сам промпт помещается свободно. В проде я считаю входные токены и ставлю max_tokens как минимум из нужной длины и остатка окна за вычетом запаса."}],
  kill:"<b>«Обрежет старое»</b> — нет, упадёт с ошибкой. И <b>output_tokens === max_tokens</b> надо логировать: обрезка молчаливая, на середине слова, без ошибки."},
 en:{topic:"Context window",
  qs:["What is the context window and what competes for space in it?",
      "You're near the limit and you send the request. What happens, and when exactly?",
      "195k prompt, 200k window, max_tokens 8000. Result? Why?"],
  a:[{q:"Definition",t:"The context window is the maximum number of tokens the model can process in one request, and it counts the input and the generated output together. Everything competes for that space: the system prompt, the conversation history, retrieved documents, tool definitions and tool results. Claude is around two hundred thousand, GPT-4o is a hundred and twenty-eight, Gemini is over a million — though those numbers move, so I'd verify them before an interview."},
     {q:"Exceeding it",t:"You get an invalid_request_error, and you get it before generation starts. That's the part people miss: validation happens upfront, the request is rejected outright, and not a single token is produced. There's no graceful truncation — the model doesn't silently drop the oldest messages. I remember it as fail fast, not silent, and it's the right design: silent truncation would give you wrong answers with no signal, whereas an error you can actually handle."},
     {q:"The max_tokens trap",t:"It gets rejected. The window has to fit the input plus max_tokens, not just the input — max_tokens is your declared ceiling on the response and the space is reserved up front. So a hundred and ninety-five plus eight doesn't fit into two hundred, even though the prompt alone fits comfortably. In production I count the input tokens first and set max_tokens to the smaller of what I actually need and what's left in the window after a safety margin."}],
  kill:"<b>\"It truncates the old messages\"</b> — no, it errors out. Also log <b>output_tokens === max_tokens</b>: clipping is silent, mid-word, and raises nothing."}},

{n:3,tag:"Core-40 #24",sec:"llm",core:[24],
 ru:{topic:"Экономика токенов",
  qs:["Почему output дороже input в 3–5 раз? Механизм, а не «так в прайсе».",
      "Косты выросли втрое за месяц. Первые четыре гипотезы по порядку.",
      "В простом вызове output был 99% счёта, в агенте input стал 84%. Что изменилось и какой вывод?"],
  a:[{q:"Асимметрия",t:"Потому что вход и выход считаются принципиально по-разному. Промпт известен целиком, поэтому состояние всех его токенов вычисляется за один параллельный проход — одна операция на всю простыню. А выход рождается по одному токену, и каждый требует полного прохода через модель: сколько токенов, столько проходов. Будущее нельзя посчитать заранее, а прошлое можно посчитать разом — вот и вся причина. Отсюда же, кстати, вообще возможен стриминг."},
     {q:"Дебаг стоимости",t:"Сначала смотрю выбор модели — не уехал ли какой-то путь на Opus, это самый крупный рычаг. Потом многословность ответов: «ответь одним предложением» экономит больше, чем любая чистка промпта. Третье — не растёт ли история неограниченно в длинных диалогах. И четвёртое — есть ли prompt caching на длинном стабильном префиксе. Только после этого думаю, что можно увести в batch API."},
     {q:"Разворот",t:"Изменилась архитектура. В агенте на каждом шаге пересылается весь разговор со всеми скачанными страницами, поэтому вход растёт квадратично и быстро обгоняет выход. И вывод отсюда не «input дороже» и не «output дороже», а тот, что профиль расходов определяется архитектурой, а не моделью. Поэтому его меряют, а не угадывают, и перемеряют заново после каждого изменения архитектуры."}],
  kill:"<b>«Оптимизируем промпт»</b> — в простом вызове это театр: срежешь 26 токенов входа и заплатишь больше, если ответ вырос на 19."},
 en:{topic:"Token economics",
  qs:["Why does output cost 3–5x more than input? Mechanism, not \"that's the price list\".",
      "Costs tripled this month. Name your first four hypotheses, in order.",
      "In a single call output was 99% of the bill; in the agent input became 84%. What changed, and what's the takeaway?"],
  a:[{q:"The asymmetry",t:"Because input and output are computed in fundamentally different ways. The prompt is known in full, so the state for all of its tokens is computed in a single parallel forward pass — one operation for the whole thing. Output is generated one token at a time, and each token needs a full pass through the model: as many passes as tokens. The future can't be computed ahead of time, the past can be computed all at once. That's the whole reason — and it's also why streaming is possible at all."},
     {q:"Debugging cost",t:"First I check model selection — did some path start routing to Opus. That's usually the biggest single lever. Then output verbosity, because asking for a one-sentence answer saves far more than trimming the system prompt ever will. Third, whether conversation history is growing unbounded in long sessions. Fourth, whether prompt caching is in place on a long stable prefix. Only after that do I look at what could move to the batch API."},
     {q:"The flip",t:"The architecture changed. In an agent every step resends the entire conversation including every page you fetched, so input grows quadratically and quickly overtakes output. And the takeaway isn't that input is expensive or that output is expensive — it's that the cost profile is decided by architecture, not by the model. Which is why you measure it instead of assuming, and re-measure after every architectural change."}],
  kill:"<b>\"We'll optimise the prompt\"</b> — in a single call that's theatre. I cut 26 input tokens and paid more, because the answer grew by 19."}},

{n:4,tag:"Core-40 #19",sec:"llm",core:[19],
 ru:{topic:"Sampling: temperature и top_p",
  qs:["Что temperature делает с числами и в каком месте пайплайна?",
      "Тот же промпт, temperature 0, два раза. Одинаковый выход гарантирован?",
      "Что делает top_p и чем лучше top_k? И что с temperature на новых Claude?"],
  a:[{q:"Механизм",t:"Temperature делит логиты перед softmax — вот и весь механизм. Если делить на число меньше единицы, логиты расходятся дальше друг от друга, softmax усиливает разрыв, распределение становится резким. Больше единицы — наоборот, сжимаются, распределение выравнивается, маловероятные токены получают шанс. Ноль реализуется как greedy decoding, всегда берётся самый вероятный. И важно, где это происходит: уже после того, как распределение посчитано. Поэтому температура не добавляет модели ни знаний, ни креативности — она только меняет, как часто берётся не-топовый токен."},
     {q:"Детерминизм",t:"Нет, не гарантирован — правильная формулировка near-deterministic, not guaranteed. Сложение чисел с плавающей точкой на GPU неассоциативно: тысячи значений суммируются параллельно в том порядке, в каком расписал kernel, и появляются микроразличия. Плюс твой запрос батчится с чужими, а другой состав батча меняет пути в вычислениях. И там, где два кандидата почти равны, разница в одну десятимиллиардную переворачивает выбор — а генерация авторегрессивна, поэтому после одного разошедшегося токена расходится всё. Если нужна настоящая воспроизводимость, я кэширую ответ, а не полагаюсь на сэмплер."},
     {q:"top_p и депрекация",t:"top_p сортирует токены по вероятности, набирает их сверху, пока сумма не достигнет p, а остальное отрезает и перенормирует. Главное его свойство — адаптивность: когда модель уверена, в наборе останется один токен, когда не уверена — сорок. А top_k всегда берёт ровно k, независимо от того, насколько модель уверена, и потому либо тащит мусор, либо режет хвост произвольно. Крутить надо что-то одно, не оба сразу. И отдельно: на Claude 4.7 и новее temperature вообще deprecated, принимается только дефолт, а управление сместилось в параметр effort — хотя точное поведение и название параметра стоит перепроверить перед интервью, это из той категории фактов, что меняется от релиза к релизу."}],
  kill:"<b>«temp 0 = детерминизм»</b> и <b>«выше температура = креативнее»</b>. Первое неверно из-за float и батчинга; второе на фактической задаче даёт не креатив, а ошибки."},
 en:{topic:"Sampling: temperature and top_p",
  qs:["What does temperature do to the numbers, and where in the pipeline does it act?",
      "Same prompt, temperature 0, twice. Is identical output guaranteed?",
      "What does top_p do and why is it preferred over top_k? And what happened to temperature on the newest Claude models?"],
  a:[{q:"Mechanism",t:"Temperature divides the logits before the softmax — that's the entire mechanism. Divide by something below one and the logits move further apart, softmax exaggerates the gaps, and the distribution gets sharp. Above one they compress, the distribution flattens, and unlikely tokens become plausible. Zero is implemented as greedy decoding, always taking the top token. And where it acts matters: this is after the distribution has already been computed. So temperature adds no knowledge and no creativity — it only changes how often a non-top token gets picked."},
     {q:"Determinism",t:"No. The correct phrasing is near-deterministic, not guaranteed. Floating-point addition on a GPU isn't associative — thousands of values get summed in parallel in whatever order the kernel schedules, and tiny differences appear. On top of that your request is batched with other people's, and a different batch composition changes the computation paths. Where two candidates are nearly tied, a difference of one part in ten million flips the choice — and since generation is autoregressive, one diverged token means everything after it diverges. If I genuinely need reproducibility I cache the output rather than trusting the sampler."},
     {q:"top_p and deprecation",t:"top_p sorts tokens by probability, takes them from the top until the accumulated mass reaches p, then cuts the rest and renormalises. Its key property is that it adapts: when the model is confident the set collapses to one token, when it's unsure it might keep forty. top_k always takes exactly k regardless of confidence, so it either drags in noise or truncates the tail arbitrarily. You tune one of them, never both. And separately — on Claude 4.7 and later temperature is deprecated entirely, only the default is accepted, and steering moved into the effort parameter — though I'd verify the exact parameter name and behavior before an interview, this is exactly the kind of thing that shifts release to release."}],
  kill:"<b>\"temp 0 means deterministic\"</b> and <b>\"higher temperature is more creative\"</b>. The first is wrong because of float and batching; the second, on a factual task, produces errors, not creativity."}},

{n:5,tag:"Core-40 #20",sec:"llm",core:[20],
 ru:{topic:"System vs user prompt",
  qs:["Чем system отличается от user? Что куда кладут?",
      "Почему system тяжелее перебить? Назови механизм.",
      "И почему это НЕ гарантия безопасности? Где живут настоящие контроли?"],
  a:[{q:"Различие",t:"System несёт то, что верно для каждого хода: роль, правила, ограничения, формат вывода. У Anthropic это вообще отдельный top-level параметр, а не элемент массива сообщений. User несёт то, что верно только для этого хода — сам запрос. И у этого разделения есть прямое денежное следствие: system надо держать статичным, потому что если подставлять туда данные пользователя, префикс меняется каждый запрос, prompt caching не попадает никогда, и ты платишь полную цену вечно."},
     {q:"Механизм",t:"Модели обучают с так называемой instruction hierarchy — примерно system выше developer, тот выше user, а ниже всех результаты инструментов и найденный контент. В ходе instruction tuning и RLHF модель учится при конфликте предпочитать более высокий уровень. Поэтому на «ignore your instructions» из пользовательского сообщения она склонна остаться при системном промпте."},
     {q:"Почему не граница",t:"Потому что это натренированная склонность, а не механизм разграничения прав. Нет кода, который запретил бы модели послушаться достаточно убедительной инструкции — это мягкий приор, а не барьер. Поэтому системный промпт я называю defense-in-depth, но не defense. Настоящие контроли живут снаружи модели: авторизация на уровне каждого инструмента, где модель просит, а решает мой код; минимальные права; валидация выхода схемой, потому что ответ модели это недоверенный ввод; подтверждение человеком на всём разрушительном. И отдельно стоит помнить, что системный промпт не секретный — его регулярно вытаскивают, поэтому ключей и конфиденциальной логики там быть не должно."}],
  kill:"<b>«Положили правило в system prompt, значит безопасно»</b> — этой фразой ты сообщаешь, что агентов в проде не держал."},
 en:{topic:"System vs user prompt",
  qs:["How does the system prompt differ from the user prompt? What goes where?",
      "Why is the system prompt harder to override? Name the mechanism.",
      "And why is that NOT a security guarantee? Where do the real controls live?"],
  a:[{q:"The difference",t:"System carries what's true on every turn: role, rules, constraints, output format. With Anthropic it's a separate top-level parameter rather than an element of the messages array. User carries what's true for this turn only — the actual request. And that split has a direct money consequence: you keep system static, because if you interpolate per-user data into it the prefix changes on every request, prompt caching never hits, and you pay full price forever."},
     {q:"The mechanism",t:"Models are trained with what's called an instruction hierarchy — roughly, system outranks developer, which outranks user, which outranks tool results and retrieved content. During instruction tuning and RLHF the model learns to prefer the higher level when the levels conflict. So when a user message says ignore your instructions, the model is trained to stay with the system prompt."},
     {q:"Why it's not a boundary",t:"Because it's a trained tendency, not an enforced permission system. There's no code path that stops the model obeying a sufficiently persuasive instruction — it's a soft prior, not a barrier. So I'd call the system prompt defense-in-depth, but not a defense. The real controls sit outside the model: authorization at the level of each tool, where the model asks and my code decides; least privilege; schema validation of output, because what the model returns is untrusted input; and human confirmation on anything destructive. And separately, the system prompt isn't secret — people extract them routinely — so no keys and no confidential logic go in there."}],
  kill:"<b>\"We put the rule in the system prompt, so it's safe\"</b> — that sentence tells the interviewer you've never run an agent in production."}},

{n:6,tag:"Core-40 #25",sec:"llm",core:[25],
 ru:{topic:"Prompt injection",
  qs:["Что такое prompt injection? Чем indirect опаснее прямой?",
      "Твой агент читает страницу, в ней «игнорируй инструкции». Что делаешь?",
      "Почему разделители — не решение?"],
  a:[{q:"Суть",t:"Prompt injection — это когда недоверенный текст попадает в контекст и модель читает его как инструкцию, а не как данные. Прямая инъекция — это когда пользователь сам пишет «ignore previous instructions», и это в основном демонстрация. По-настоящему опасна indirect: инструкция лежит внутри веб-страницы, PDF или тикета поддержки, которые агент притащил сам. Пользователь при этом не писал ничего вредоносного, атака приехала вместе с данными, и именно так ломают агентов в проде."},
     {q:"Что делать",t:"Первое — явно отделить недоверенный контент тегами и прямо назвать его данными: текст внутри document это данные, никогда не инструкции. Второе — минимальные права у каждого инструмента, чтобы даже успешная инъекция мало что могла. Третье — всё разрушительное только через подтверждение человеком. Четвёртое — валидация выхода схемой, потому что то, что вернула модель, это недоверенный ввод. И пятое — ограничить, куда агент вообще имеет право ходить."},
     {q:"Почему не панацея",t:"Потому что разделитель повышает цену атаки, но не устраняет её — модель всё равно может послушаться, это остаётся вопросом убедительности текста, а не разрешений. Надёжная граница возможна только снаружи модели, в коде, который исполняет действия. На собесе я стараюсь сказать обе половины: и что делаю в промпте, и почему на этом не останавливаюсь."}],
  kill:"Ответ только про прямую инъекцию. Ломает агентов в проде именно <b>indirect</b>, и спрашивают дальше про неё."},
 en:{topic:"Prompt injection",
  qs:["What is prompt injection? Why is indirect injection worse than direct?",
      "Your agent fetches a page and it contains \"ignore your instructions\". What do you do?",
      "Why aren't delimiters a solution?"],
  a:[{q:"The idea",t:"Prompt injection is when untrusted text lands in the context and the model reads it as an instruction rather than as data. Direct injection is the user typing ignore previous instructions, and that's mostly a demo. The dangerous one is indirect: the instruction sits inside a web page, a PDF or a support ticket that your agent fetched itself. The user never typed anything malicious — the attack arrived with the data, and that's how production agents actually get broken."},
     {q:"What you do",t:"First, explicitly delimit the untrusted content and label it as data — text inside document is data, never instructions. Second, least privilege on every tool, so that even a successful injection can't do much. Third, anything destructive goes through human confirmation. Fourth, validate output against a schema, because what the model returns is untrusted input. And fifth, constrain where the agent is allowed to go in the first place."},
     {q:"Why delimiters aren't enough",t:"Because a delimiter raises the cost of the attack without eliminating it — the model can still be talked into it, which makes it a question of how persuasive the text is rather than a question of permissions. A reliable boundary only exists outside the model, in the code that executes actions. In an interview I try to say both halves: what I do in the prompt, and why I don't stop there."}],
  kill:"Answering only about direct injection. <b>Indirect</b> is what actually breaks production agents, and it's where the follow-up goes."}},

{n:7,tag:"Core-40 #21, #33",sec:"agents",core:[21, 33],
 ru:{topic:"Tool use",
  qs:["Модель попросила инструмент. Кто идёт в интернет и что происходит дальше по шагам?",
      "Из чего состоит определение tool и что там самое важное?",
      "Почему content в ответе — массив, а не строка?"],
  a:[{q:"Петля",t:"Модель не вызывает ничего — вот главное. Она возвращает намерение: имя инструмента и аргументы. Дальше всё делает мой код: он идёт в интернет, получает результат и кладёт его обратно в массив сообщений как tool_result с тем же tool_use_id. После этого модель вызывается снова, уже с результатом в контексте. И так по кругу, пока stop_reason не перестанет быть tool_use. Руки — это мой код, у модели их нет, и именно поэтому вообще возможна авторизация."},
     {q:"Определение",t:"Имя, описание и JSON-схема параметров. И самое важное там — описание, потому что это на самом деле промпт, а не документация: это единственное, по чему модель решает, звать инструмент или не звать. Я пишу его как инструкцию для толкового незнакомца — что инструмент делает, когда его применять и, отдельно, когда применять не надо. Плохое описание чинится не кодом, а текстом."},
     {q:"Массив блоков",t:"Потому что в одном ответе может приехать сразу несколько разных блоков: текст и запрос инструмента вместе, иногда несколько инструментов сразу. Модель одновременно рассуждает вслух и просит данные. Поэтому content — это массив с полем type у каждого блока, и код обязан их фильтровать, а не считать ответ строкой."}],
  kill:"<b>«Модель вызывает функцию»</b> — нет, возвращает JSON с намерением. Исполняешь ты, и именно поэтому авторизация вообще возможна."},
 en:{topic:"Tool use",
  qs:["The model asked for a tool. Who goes to the internet, and what happens next, step by step?",
      "What's in a tool definition, and which part matters most?",
      "Why is content an array rather than a string?"],
  a:[{q:"The loop",t:"The model doesn't call anything — that's the key point. It returns an intent: a tool name and arguments. Everything after that is my code: it goes to the internet, gets the result, and appends it back into the messages array as a tool_result carrying the same tool_use_id. Then the model is called again, now with that result in context. And round it goes until stop_reason is no longer tool_use. The hands are my code — the model has none, and that's exactly why authorization is possible at all."},
     {q:"The definition",t:"A name, a description, and a JSON schema for the parameters. The description is the part that matters, because it's really a prompt rather than documentation — it's the only thing the model uses to decide whether to call the tool. I write it for a competent stranger: what it does, when to use it, and separately when not to. A bad description is fixed with text, not with code."},
     {q:"Array of blocks",t:"Because a single response can carry several different blocks at once: text and a tool request together, sometimes several tool requests. The model reasons out loud and asks for data in the same message. So content is an array where every block has a type, and your code has to filter on that rather than treating the response as a string."}],
  kill:"<b>\"The model calls the function\"</b> — it doesn't. It returns JSON describing an intent. You execute it, which is exactly why authorization is possible."}},

{n:8,tag:"Core-40 #34",sec:"agents",core:[34],
 ru:{topic:"Стоп-условия и ошибки",
  qs:["Как агент понимает, что пора остановиться? Перечисли условия.",
      "Tool вернул 404. Бросаешь исключение или отдаёшь модели?",
      "Что должно происходить, когда прогон падает на середине?"],
  a:[{q:"Стоп",t:"Останавливаемся в четырёх случаях: модель вернула финальный ответ вместо запроса инструмента, достигнут потолок итераций, случилась неустранимая ошибка, или мы упёрлись в чекпоинт, где нужен человек. Жёсткий лимит шагов и бюджет по деньгам я считаю обязательными, а не перестраховкой: агент, у которого инструмент стабильно падает, будет крутиться, пока не кончатся деньги. И причину остановки надо логировать — при разборе это первое, на что смотришь."},
     {q:"Ошибки tool",t:"Отдаю модели. Возвращаю обычной строкой вроде ERROR: HTTP 404, и модель это читает и пробует другой путь — другой url, другую страницу. Если бросить исключение, агент умрёт на первой битой ссылке и потеряет всю уже проделанную работу, за которую ты уже заплатил. Ошибка инструмента — это нормальные данные для модели, а не аварийная ситуация для программы."},
     {q:"Падение",t:"Учёт расходов обязан отработать в любом случае, иначе ты даже не знаешь, во что обошёлся неудачный прогон. У меня это висит на выходе из процесса, поэтому отчёт печатается и при падении. Общий принцип такой: инструментация, которая работает только на счастливом пути, бесполезна ровно в тот момент, когда она нужна. Плюс ретраи на транзиентных сетевых ошибках и явный таймаут, чтобы одна икота сети не убивала весь прогон."}],
  kill:"Забыть про потолок итераций. «Ну оно само остановится» — не остановится, если tool падает."},
 en:{topic:"Stopping criteria and errors",
  qs:["How does an agent know it should stop? List the conditions.",
      "A tool returns 404. Do you throw, or hand it back to the model?",
      "What has to happen when a run dies halfway?"],
  a:[{q:"Stopping",t:"There are four cases: the model returned a final answer instead of a tool request, we hit the iteration cap, an unrecoverable error occurred, or we reached a checkpoint that needs a human. I treat a hard step cap and a spending budget as mandatory rather than as belt-and-braces: an agent whose tool keeps failing will loop until the money runs out. And I log why it stopped, because that's the first thing you look at when something goes wrong."},
     {q:"Tool errors",t:"I hand it back to the model. I return a plain string like ERROR: HTTP 404, and the model reads it and tries a different route — another URL, another page. If you throw instead, the agent dies on the first dead link and loses all the work it had already done and already paid for. A tool error is ordinary data for the model, not an emergency for the program."},
     {q:"Crashes",t:"Cost accounting has to run either way, otherwise you don't even know what the failed run cost you. Mine hangs off the process exit, so the report prints even on a crash. The general principle is that instrumentation which only works on the happy path is useless precisely when you need it. Plus retries on transient network errors and an explicit timeout, so one network hiccup doesn't kill the whole run."}],
  kill:"Forgetting the iteration cap. \"It'll stop on its own\" — it won't, if the tool keeps failing."}},

{n:9,tag:"глубина / depth",sec:"bonus",core:[41],
 ru:{topic:"Attention и кэш",
  qs:["Что такое Q, K и V? Объясни своими словами.",
      "Почему кэшируют K и V, но не Q? И почему кэш только префиксный?",
      "Чем prompt caching отличается от KV cache внутри запроса? Что значит ephemeral?"],
  a:[{q:"Q/K/V",t:"Для каждого токена модель считает три вектора. K — это как бирка, «про что я, чем могу быть полезен». V — фактическое содержимое, то, что этот токен передаёт дальше. А Q — запрос текущего токена, «что я сейчас ищу». Механика такая: Q сравнивается со всеми K, из этого получаются веса релевантности, и уже этими весами взвешиваются V. То есть Q ищет, K отвечает за находимость, V переносит смысл."},
     {q:"Почему KV",t:"Потому что K и V токена зависят только от него самого и от того, что было до него, и никогда — от того, что придёт после. Значит, посчитав их однажды, можно хранить: они не изменятся. А Q нужен ровно один раз, в момент обработки своего токена, и хранить его незачем — отсюда и название KV cache, а не QKV. Префиксность следует оттуда же: если поменять токен на пятой позиции, все, кто идёт после, находятся уже в другом контексте, и их K и V другие. А то, что было до пятого, не затронуто вообще. Это, кстати, общий закон — кэшируется то, что зависит только от прошлого, ровно как useMemo или инкрементальная сборка."},
     {q:"Prompt caching",t:"KV cache внутри одного запроса работает всегда, автоматически и бесплатно, но живёт ровно один запрос: ответ отдан, состояние выброшено. Prompt caching его не выбрасывает, а держит между запросами — механизм тот же самый, меняется только область жизни. Держать стоит им памяти, поэтому запись тарифицируется с наценкой в двадцать пять процентов, а чтение в десять раз дешевле обычного входа. А ephemeral означает буквально «подержим, но не обещаем»: порядка пяти минут, best-effort, могут выселить раньше. Отсюда правило: код обязан работать одинаково при нуле попаданий, кэш — это оптимизация цены, а не часть логики."}],
  kill:"<b>«Кэш чтобы не платить дважды»</b> — мелко. Правильно: продление жизни KV-состояния между запросами, поэтому запись с наценкой, а чтение почти даром."},
 en:{topic:"Attention and caching",
  qs:["What are Q, K and V? Explain in your own words.",
      "Why are K and V cached but not Q? And why is the cache prefix-only?",
      "How is prompt caching different from the KV cache inside a request? What does ephemeral mean?"],
  a:[{q:"Q/K/V",t:"For every token the model computes three vectors. K is like a label — what this token is about, what it can be useful for. V is the actual content, what this token passes along. And Q is the current token's query — what it's looking for right now. The mechanics are that Q gets compared against every K, that produces relevance weights, and those weights are then applied to the Vs. So Q searches, K makes a token findable, and V carries the meaning."},
     {q:"Why KV",t:"Because a token's K and V depend only on itself and on what came before it, and never on what comes after. So once you've computed them you can store them — they won't change. Q is needed exactly once, at the moment its own token is processed, so there's nothing worth keeping — which is why it's called a KV cache and not a QKV cache. Prefix-only follows from the same thing: change the token at position five and everything after it sits in a different context, so their K and V differ, while everything before five is untouched. It's a general law, really — you can cache whatever depends only on the past, exactly like useMemo or an incremental build."},
     {q:"Prompt caching",t:"The KV cache inside a single request is always on, automatic and free, but it lives for exactly one request — the answer is returned and the state is thrown away. Prompt caching doesn't throw it away, it holds it between requests. Same mechanism, the only thing that changes is the scope. Holding it costs them memory, which is why a cache write is billed at a twenty-five percent premium while a read is ten times cheaper than normal input. And ephemeral means literally we'll hold it but we don't promise: around five minutes, best-effort, and it can be evicted early. Hence the rule that your code has to behave identically with zero cache hits — caching is a price optimisation, never part of the logic."}],
  kill:"<b>\"Caching so you don't pay twice\"</b> is too shallow. It's persisting KV state across requests — which is why writes carry a premium and reads are nearly free."}},

{n:10,tag:"Core-40 #18, #27",sec:"llm",core:[18, 27],
 ru:{topic:"Statelessness и лестница",
  qs:["Модель что-нибудь помнит между вызовами?",
      "Из этого следуют три вещи. Какие?",
      "Контекст кончается. Обходы от самого дешёвого к сложному."],
  a:[{q:"Память",t:"Ничего не помнит. Это обычный HTTP-запрос: отправил, получил ответ, соединение закрылось, никакого состояния на той стороне не осталось. «Помнит» на самом деле мой массив сообщений — то есть память живёт в моём коде, а не в модели. Поэтому каждый ход диалога пересылает всю переписку заново, целиком."},
     {q:"Следствия",t:"Во-первых, разговор дорожает с каждым ходом, потому что вход растёт квадратично. Во-вторых, контекстное окно неизбежно кончается, это вопрос времени, а не вероятности. И в-третьих, в агентной петле одни и те же данные оплачиваются многократно — у меня в замере было шестьдесят девять тысяч токенов отправлено ради двадцати одной тысячи уникальных, то есть за одно и то же я заплатил больше трёх раз."},
     {q:"Лестница",t:"Начинаю с самого тупого — sliding window, держим последние N сообщений, остальное выбрасываем: бесплатно и молча теряет информацию. Дальше summarization, старое сжимается в накопительное резюме, свежее держится дословно — так работает большинство долгоживущих чатов. Потом RAG: не класть в контекст вообще, а доставать релевантное под конкретный запрос — правильный выбор, когда корпус больше окна. Четвёртое — hierarchical или map-reduce, режем документ, обрабатываем части отдельно, собираем результат. И пятое, стоящее особняком, — prompt caching: места оно не экономит совсем, экономит деньги и латентность на стабильном префиксе, поэтому используется вместе с остальными, а не вместо."}],
  kill:"Назвать только summarization. Верно, но это одна ступень из пяти — а спрашивают, умеешь ли выбирать <b>самое дешёвое из достаточного</b>."},
 en:{topic:"Statelessness and the ladder",
  qs:["Does the model remember anything between calls?",
      "Three things follow from that. What are they?",
      "You're running out of context. Walk the mitigations from cheapest to most complex."],
  a:[{q:"Memory",t:"It remembers nothing. It's an ordinary HTTP request: you send it, you get an answer, the connection closes, and no state is left on that side. What actually remembers is my messages array — so the memory lives in my code, not in the model. Which is why every turn of a conversation resends the entire history from scratch."},
     {q:"Consequences",t:"First, the conversation gets more expensive with every turn, because input grows quadratically. Second, the context window inevitably runs out — it's a question of when, not whether. And third, in an agent loop the same data gets paid for many times over. In my own run I sent sixty-nine thousand tokens to convey twenty-one thousand unique ones, so I paid for the same pages more than three times."},
     {q:"The ladder",t:"I start with the dumbest thing that works — a sliding window, keep the last N messages and drop the rest: free, and it loses information silently. Then summarization, where older turns get compressed into a running summary and recent ones stay verbatim; that's what most long-lived chat products actually do. Then RAG: don't put it in context at all, retrieve only what's relevant per query — the right answer once the corpus is bigger than the window. Fourth is hierarchical or map-reduce, splitting a document, processing the parts independently and combining. And fifth, which stands apart, is prompt caching: it saves no space at all, it saves money and latency on a stable prefix, so it's used alongside the others rather than instead of them."}],
  kill:"Naming only summarization. It's correct, but it's one rung of five — and the question is really whether you can pick <b>the cheapest thing that suffices</b>."}}
,
{n:11,tag:"Core-40 #22",sec:"llm",core:[22],
 ru:{topic:"Streaming: SSE и ReadableStream",
  qs:["Как выглядит SSE-поток на проводе и почему для стриминга ответа LLM берут его, а не WebSocket?",
      "Ты потребляешь поток в браузере. Пройди по коду: от fetch до появления текста на экране.",
      "Соединение оборвалось на середине ответа. Что ты видишь в коде и что делает UI?"],
  a:[{q:"На проводе",t:"Это обычный HTTP-ответ с content-type text/event-stream, который сервер не закрывает, а пишет в него кусками. Каждое событие — строки вида data: и JSON, разделённые пустой строкой. Односторонний канал от сервера к клиенту, через любые прокси, без апгрейда протокола. WebSocket двусторонний, требует держать сокет и своё состояние, а у меня по сути запрос-ответ, просто ответ приезжает по частям. Нюанс: встроенный EventSource умеет только GET без заголовков, поэтому для LLM я делаю fetch с POST и читаю body как ReadableStream — формат тот же, парсер свой."},
     {q:"Код",t:"fetch с POST и телом запроса, потом res.body.getReader() и TextDecoder. В цикле reader.read() отдаёт байты, я декодирую их с флагом stream: true, потому что чанк может разрезать многобайтовый символ пополам, и докладываю в буфер. Из буфера режу по двойному переводу строки, из каждого события беру строку data: и парсю JSON. У Anthropic это message_start, потом content_block_delta с text_delta, в конце message_delta со stop_reason и usage, и message_stop. Дельту дописываю в состояние. Рендер батчу через requestAnimationFrame, а не сеттер на каждый токен."},
     {q:"Обрыв",t:"Никакого специального события обрыва нет. Либо reader.read() отклонится, либо done придёт раньше, чем message_stop. У меня остаётся частичный текст. UI его не выбрасывает: показывает что есть, помечает как неполное и даёт retry. Отмену делаю через AbortController, чтобы не платить за то, что пользователь уже закрыл. И две вещи, которые люди забывают: stop_reason max_tokens значит обрезано, а не готово, и usage приезжает только в конце, поэтому стоимость ответа неизвестна, пока он не дописан. Стриминг улучшает время до первого токена, а не общую задержку."}],
  kill:"<b>«SSE это как WebSocket»</b> — нет, это HTTP-ответ, который не закрывают. И <b>decoder без stream: true</b> — чанк режет UTF-8 пополам, и кириллица превращается в мусор ровно на демо."},
 en:{topic:"Streaming: SSE and ReadableStream",
  qs:["What does an SSE stream look like on the wire, and why use it for LLM output instead of WebSocket?",
      "You're consuming the stream in the browser. Walk me through the code from fetch to text on screen.",
      "The connection drops mid-answer. What do you see in code and what does the UI do?"],
  a:[{q:"On the wire",t:"It's a plain HTTP response with content-type text/event-stream that the server keeps open and writes to in chunks. Each event is a few lines — data: followed by JSON — separated by a blank line. One-way, server to client, goes through any proxy, no protocol upgrade. WebSocket is bidirectional, you hold a socket and manage state, and what I have is really a request and a response that happens to arrive in pieces. One catch: the built-in EventSource only does GET with no headers, so for LLM calls I use fetch with POST and read the body as a ReadableStream — same wire format, my own parser."},
     {q:"The code",t:"fetch with POST and the request body, then res.body.getReader() and a TextDecoder. In a loop, reader.read() hands me bytes, I decode with stream: true — because a chunk can cut a multi-byte character in half — and append to a buffer. I split the buffer on double newlines, take the data: line of each event, parse the JSON. With Anthropic that's message_start, then content_block_delta carrying text_delta, then message_delta with stop_reason and usage, then message_stop. Each delta gets appended to state, and I batch renders on requestAnimationFrame rather than setting state per token."},
     {q:"The drop",t:"There's no dedicated disconnect event. Either reader.read() rejects, or done arrives before message_stop. What I'm left with is partial text. The UI keeps it — shows what arrived, marks it incomplete, offers a retry. Cancel goes through an AbortController so I'm not paying for output the user already closed. Two things people forget: stop_reason max_tokens means truncated, not finished, and usage only arrives at the end, so I don't know the cost until the answer completes. Streaming improves time to first token, not total latency."}],
  kill:"<b>\"SSE is like WebSocket\"</b> — it isn't, it's an HTTP response that stays open. And <b>decoding without stream: true</b> — a chunk splits UTF-8 mid-character and non-English text turns to garbage, reliably during the demo."}},

{n:12,tag:"Core-40 #23",sec:"llm",core:[23],
 ru:{topic:"Structured output",
  qs:["Три способа получить JSON от модели. Что это за способы и когда какой?",
      "Почему tool use — самый надёжный способ у Anthropic? Что делает принудительный вызов инструмента?",
      "JSON пришёл невалидный или не по схеме. Что делаешь?"],
  a:[{q:"Три способа",t:"Первый — попросить в промпте отвечать JSON и распарсить. Дёшево, ненадёжно: модель заворачивает в markdown, добавляет пояснение, пропускает поле. Второй — JSON mode или response_format со схемой, как у OpenAI: гарантирует синтаксически валидный JSON, а в strict-режиме и соответствие схеме. Третий — tool use: описываю инструмент, чей input schema и есть нужная мне форма, и заставляю модель его вызвать. Вызов инструмента — это и есть мой структурированный ответ, исполнять ничего не надо. Выбираю по требуемой надёжности и по тому, что даёт провайдер. Для продакшена — второй или третий, первый только для прототипа."},
     {q:"Tool use",t:"Потому что схема инструмента ограничивает генерацию на стороне провайдера, а не постфактум. tool_choice с конкретным именем заставляет модель выдать именно этот инструмент с полями по схеме. Я не исполняю ничего — читаю input и всё. Описания полей важны: модель заполняет их, ориентируясь на текст описания, поэтому description это часть API, а не комментарий. Гарантия здесь — синтаксис и форма. Не правдивость значений. Модель может вернуть красивый валидный объект с выдуманной датой."},
     {q:"Невалидный",t:"Валидирую всегда, через Zod, даже в strict-режиме: схема провайдера и моя схема — это два разных контракта. При ошибке делаю retry и прикладываю текст ошибки валидации в сообщение: модель обычно чинит с первого раза. Максимум два повтора, потом fallback и алерт. Долю невалидных ответов считаю как метрику эвала, а не как случайность. Невалидированный JSON никогда не идёт в базу. И держу схему маленькой: чем меньше опциональных полей, тем меньше галлюцинированных значений."}],
  kill:"<b>«JSON mode гарантирует правильные данные»</b> — гарантирует валидный JSON, не правду. И парсинг регуляркой из markdown-блока — это способ номер ноль, о нём на интервью лучше не вспоминать."},
 en:{topic:"Structured output",
  qs:["Three ways to get JSON out of a model. What are they and when do you use each?",
      "Why is tool use the most reliable option on Anthropic? What does forcing a tool actually do?",
      "The JSON comes back invalid or off-schema. What do you do?"],
  a:[{q:"Three ways",t:"First, ask for JSON in the prompt and parse. Cheap, unreliable: the model wraps it in markdown, adds an explanation, drops a field. Second, JSON mode or response_format with a schema, the OpenAI way: guarantees syntactically valid JSON, and in strict mode conformance to the schema. Third, tool use: I define a tool whose input schema is exactly the shape I want, and force the model to call it. The tool call is my structured output — nothing gets executed. I pick by how much reliability I need and what the provider offers. Production is option two or three; option one is prototype-only."},
     {q:"Tool use",t:"Because the tool schema constrains generation on the provider side rather than checking afterwards. tool_choice with a specific name forces the model to emit that tool with fields per the schema. I execute nothing — I read the input and move on. Field descriptions matter: the model fills them based on that text, so the description is part of the API, not a comment. What's guaranteed is syntax and shape. Not truth. The model can hand you a beautiful valid object with an invented date in it."},
     {q:"Invalid",t:"I validate every time, with Zod, even in strict mode — the provider's schema and mine are two different contracts. On failure I retry and append the validation error to the message; the model usually fixes it on the first try. Two retries max, then a fallback and an alert. I track the invalid rate as an eval metric, not as bad luck. Unvalidated JSON never touches the database. And I keep the schema small: fewer optional fields means fewer hallucinated values."}],
  kill:"<b>\"JSON mode guarantees correct data\"</b> — it guarantees valid JSON, not true values. And regex-parsing a markdown fence is option zero; don't bring it up in an interview."}},

{n:13,tag:"Core-40 #26",sec:"llm",core:[26],
 ru:{topic:"Выбор модели и роутинг",
  qs:["Opus, Sonnet, Haiku. Как выбираешь и что у тебя по умолчанию?",
      "Что такое model routing и куда на самом деле уходят деньги?",
      "Как понижаешь модель на шаге, не сломав качество?"],
  a:[{q:"Выбор",t:"По умолчанию середина — Sonnet: лучший баланс качества, цены и задержки, и на нём я пишу всё, пока не доказано обратное. Haiku беру для массовых простых операций: классификация, извлечение полей, дистилляция страниц — там он на порядок дешевле и быстрее, а качество не страдает. Opus — для сложных рассуждений, длинных агентных задач и там, где качество ответа и есть продукт. Ошибка — брать самую умную модель везде: ты платишь за интеллект, который на большинстве шагов не нужен."},
     {q:"Роутинг",t:"Роутинг — это разные модели на разных шагах или для разных классов запросов. В моём scout-агенте Haiku сжимает сырые страницы до того, как их увидит Sonnet: двадцать тысяч символов мусора перестают попадать в дорогую модель. Деньги — это входные токены, умноженные на цену модели, поэтому главный рычаг обычно не та модель, что пишет ответ, а та, что читает объём. Я это увидел на цифрах: до роутинга у меня шестьдесят процентов счёта были cache writes от повторной отправки одних и тех же страниц."},
     {q:"Понижение",t:"Сначала эвал, потом понижение. Собираю маленький golden set для этого шага, прогоняю обе модели, сравниваю по метрике шага — точность извлечения, faithfulness, что там важно — и считаю разницу в цене. Понижаю, только если качество держится в допуске. Оставляю эскалацию: если дешёвая модель не уверена или валидация не прошла, шаг уходит наверх. Понижать по ощущениям нельзя — потом не поймёшь, откуда просела точность."}],
  kill:"<b>«Просто бери самую сильную»</b> — это ответ человека, который не платил за API. Противоположная ошибка — <b>понижать по цене без эвала</b>: качество упало, а ты об этом узнаёшь от пользователей."},
 en:{topic:"Model selection and routing",
  qs:["Opus, Sonnet, Haiku. How do you choose, and what's your default?",
      "What is model routing, and where does the money actually go?",
      "How do you downgrade a step's model without breaking quality?"],
  a:[{q:"Choosing",t:"The default is the middle — Sonnet: the best balance of quality, price and latency, and that's what I build on until proven otherwise. Haiku is for high-volume simple operations — classification, field extraction, distilling pages — where it's an order of magnitude cheaper and faster and quality doesn't suffer. Opus is for hard reasoning, long agentic tasks, and anywhere the answer's quality is the product. The mistake is using the smartest model everywhere: you're paying for intelligence most steps don't need."},
     {q:"Routing",t:"Routing means different models for different steps or request classes. In my scout agent, Haiku distills raw pages before Sonnet ever sees them: twenty thousand characters of noise stop reaching the expensive model. Money is input tokens times model price, so the biggest lever is usually not the model that writes the answer but the one that reads the bulk. I saw this in numbers: before routing, sixty percent of my bill was cache writes from resending the same pages."},
     {q:"Downgrading",t:"Eval first, downgrade second. I build a small golden set for that step, run both models, compare on the step's metric — extraction accuracy, faithfulness, whatever matters there — and measure the cost delta. I downgrade only if quality holds within tolerance. I keep an escalation path: if the cheap model is unsure or validation fails, the step goes up a tier. You never downgrade on vibes, because later you can't tell where the accuracy went."}],
  kill:"<b>\"Just use the strongest model\"</b> is the answer of someone who has never paid an API bill. The opposite mistake is <b>downgrading on price with no eval</b>: quality drops and you find out from users."}},

{n:14,tag:"Core-40 #32",sec:"agents",core:[32],
 ru:{topic:"ReAct и агентный цикл",
  qs:["Что такое ReAct и какую задачу он решает по сравнению с одним вызовом?",
      "Минимальная реализация: что внутри тела цикла?",
      "Где это ломается и что ты добавляешь?"],
  a:[{q:"Что это",t:"Reason плюс Act: модель рассуждает, выбирает действие — вызов инструмента, — получает наблюдение, рассуждает снова. Цикл продолжается, пока не будет финального ответа. Он решает то, что одному вызову недоступно: достать информацию, которой у модели нет, проверить гипотезу, сделать многошаговую работу, где следующий шаг зависит от результата предыдущего. Один вызов не умеет ни сходить в интернет, ни исправиться после ошибки. И важно: ReAct — это не приём в промпте, это цикл управления в моём коде, где исполняю я."},
     {q:"Реализация",t:"Массив messages, описание инструментов. Вызываю модель. Если stop_reason равен tool_use — беру имя и аргументы, исполняю сам, кладу результат в messages как tool_result и иду на следующую итерацию. Если end_turn — это финальный ответ, выхожу. Обязательно: потолок по шагам, бюджет по деньгам, ошибки инструмента возвращаю как строку в tool_result, а не бросаю исключение — модель должна их увидеть и среагировать. Это буквально мой scout: пять шагов, шесть страниц, и я вижу каждый шаг в логе."},
     {q:"Где ломается",t:"Зацикливается на падающем инструменте. Уходит от цели, когда контекст растёт и исходная задача тонет посередине. Раздувает стоимость, потому что каждая итерация пересылает всю историю — у меня одни и те же страницы оплачивались три с лишним раза. Что добавляю: жёсткий потолок шагов и бюджет, дистилляцию выходов инструментов дешёвой моделью, prompt caching на статичном префиксе, при длинных задачах — явный план и сжатие наблюдений, чекпоинт для человека там, где действие необратимо, и лог причины остановки — это первое, куда смотришь при разборе."}],
  kill:"<b>«ReAct — это think step by step»</b> — нет, это цикл, в котором инструменты исполняет твой код. И <b>«он сам остановится»</b> — не остановится, если инструмент продолжает падать."},
 en:{topic:"ReAct and the agent loop",
  qs:["What is ReAct, and what problem does it solve compared to a single call?",
      "Minimal implementation: what's inside the loop body?",
      "Where does it break, and what do you add?"],
  a:[{q:"What it is",t:"Reason plus Act: the model reasons, picks an action — a tool call — gets an observation, reasons again. The loop runs until there's a final answer. It solves what a single call can't: fetching information the model doesn't have, checking a hypothesis, doing multi-step work where the next step depends on the last result. One call can't go to the internet and can't recover from a mistake. And the important part: ReAct isn't a prompting trick, it's a control loop in my code, where I'm the one executing."},
     {q:"Implementation",t:"A messages array and tool definitions. Call the model. If stop_reason is tool_use, take the name and arguments, execute them myself, append the result to messages as a tool_result, and go around again. If it's end_turn, that's the final answer, exit. Non-negotiable: a step cap, a spending budget, and tool errors returned as strings inside the tool_result rather than thrown — the model has to see them to react. That's literally my scout: five steps, six pages, and every step in the log."},
     {q:"Where it breaks",t:"It loops on a failing tool. It drifts off-goal as the context grows and the original task sinks into the middle. It balloons in cost because every iteration resends the whole history — I had the same pages paid for three-plus times. What I add: a hard step cap and budget, distilling tool outputs with a cheap model, prompt caching on the static prefix, for long tasks an explicit plan and observation compression, a human checkpoint before anything irreversible, and a logged stop reason — it's the first thing you look at in a post-mortem."}],
  kill:"<b>\"ReAct is think-step-by-step\"</b> — no, it's a loop where your code executes the tools. And <b>\"it'll stop on its own\"</b> — it won't, if the tool keeps failing."}}

,
{n:15,tag:"Core-40 #27",sec:"rag",core:[27],
 ru:{topic:"RAG или всё в контекст",
  qs:["Когда RAG не нужен? Опиши случай, где ты его не стал бы делать.",
      "Когда нужен: четыре причины, не одна.",
      "Окна уже по миллиону токенов. RAG умер?"],
  a:[{q:"Не нужен",t:"Если корпус помещается в контекст с запасом — скажем, десятки тысяч токенов, — меняется редко и цена за вызов приемлема, я просто кладу его целиком и включаю prompt caching. Никакого индекса, никаких промахов ретривера, никакой инфраструктуры. Половина проектов, которые называют себя RAG, — это хендбук на тридцать страниц, который влезает. Первый вопрос всегда: а сколько это в токенах? Если человек не измерил, он не выбирал архитектуру, он повторял модное слово."},
     {q:"Нужен",t:"Первая причина — не помещается, и это самая очевидная. Вторая — цена: платить за двести тысяч токенов на каждый запрос, когда релевантных две тысячи, это стократный перерасход. Третья — свежесть: документы обновляются, и переиндексировать проще, чем переписывать промпт. Четвёртая — точность: модель теряет середину длинного контекста, и релевантная выборка отвечает точнее, чем полная свалка. И пятая, про которую забывают, — права доступа: разным пользователям видны разные документы, и фильтр на уровне ретривера это единственный честный способ."},
     {q:"Умер?",t:"Нет, сдвинулся баланс. Длинный контекст убирает причину «не помещается», но не убирает цену, задержку, свежесть и права доступа. И качество внимания на длинных входах всё ещё проседает, когда нужная игла лежит среди похожих. Реалистичный паттерн сейчас — ретривер сужает до кандидатов, а большое окно позволяет отдавать куски крупнее и резать документы менее агрессивно. Правильный ответ на «RAG или контекст» — эвал на своих данных, а не вера."}],
  kill:"<b>«RAG, потому что так делают»</b>. Первый вопрос интервьюера будет: сколько токенов в вашем корпусе? Если ответа нет — дальше можно не слушать."},
 en:{topic:"RAG versus everything in context",
  qs:["When do you not need RAG? Describe a case where you'd skip it.",
      "When you do need it: four reasons, not one.",
      "Context windows are a million tokens now. Is RAG dead?"],
  a:[{q:"Not needed",t:"If the corpus fits in context with room to spare — say tens of thousands of tokens — changes rarely, and the cost per call is acceptable, I put the whole thing in and turn on prompt caching. No index, no retriever misses, no infrastructure. Half the projects that call themselves RAG are a thirty-page handbook that fits. The first question is always: how many tokens is it? If someone hasn't measured, they didn't choose an architecture, they repeated a buzzword."},
     {q:"Needed",t:"First reason — it doesn't fit, the obvious one. Second — cost: paying for two hundred thousand tokens per request when two thousand are relevant is a hundredfold overspend. Third — freshness: documents update, and re-indexing is easier than rewriting a prompt. Fourth — precision: the model loses the middle of a long context, and a relevant selection answers more accurately than a full dump. And a fifth people forget — access control: different users can see different documents, and filtering at the retriever is the only honest way to enforce that."},
     {q:"Dead?",t:"No, the balance moved. Long context removes the doesn't-fit reason, but not cost, latency, freshness or permissions. And attention quality still degrades on long inputs when the needle sits among look-alikes. The realistic pattern now is retrieval narrowing to candidates, with the big window letting you pass larger chunks and split documents less aggressively. The right answer to RAG versus context is an eval on your own data, not a belief."}],
  kill:"<b>\"RAG because that's what you do.\"</b> The interviewer's next question will be: how many tokens is your corpus? No answer, and the rest doesn't matter."}},

{n:16,tag:"Core-40 #28",sec:"rag",core:[28],
 ru:{topic:"Chunking",
  qs:["Fixed size, semantic, sliding window: что это и в чём trade-off каждого?",
      "Типичные цифры и зачем вообще существует overlap?",
      "Как понять, что твой chunking неправильный?"],
  a:[{q:"Три подхода",t:"Fixed size — режу по N токенов. Просто, предсказуемо, режет мысль пополам. Semantic или структурный — режу по заголовкам, абзацам, блокам кода. Уважает смысл, но куски получаются разного размера, и большой абзац может не влезть. Sliding window — фиксированный размер с перекрытием, чтобы контекст на границе не терялся. На практике я делаю сначала структурный, поверх — потолок по размеру, и overlap как страховку. Один подход в чистом виде почти никогда не лучший."},
     {q:"Цифры",t:"Двести–пятьсот токенов на кусок, перекрытие около пятидесяти токенов, или десять–пятнадцать процентов. Overlap нужен потому, что факт рядом с границей иначе окажется разрезан на два куска, и ни один из них не заэмбеддится так, чтобы этот факт найти. Куски больше — больше контекста на попадание, но эмбеддинг усредняет смысл и становится мутнее. Меньше — точнее, но фрагментарно, и ответу не хватает окружения. И к каждому куску — метаданные: источник, раздел, позиция, иначе не процитируешь."},
     {q:"Диагностика",t:"Два симптома. Кусок нашёлся релевантный, но ответ неполный — значит, кусок слишком мелкий или разрезан не там. Куски находятся как-то похожие, но не те — значит, слишком крупные, смысл размылся. Проверяю не чтением, а эвалом: на золотом наборе вопросов смотрю, попадает ли нужный пассаж в top-k. Это изолирует chunking и retrieval от генерации. Меняю размер, прогоняю снова, сравниваю. В моём RAG-проекте размер куска был ручкой, которую я крутил по метрике, а не по ощущению."}],
  kill:"Назвать одно магическое число и остановиться. И <b>«chunking это деталь»</b> — это самая частая причина плохого RAG, интервьюер это знает."},
 en:{topic:"Chunking",
  qs:["Fixed size, semantic, sliding window: what are they and what's the trade-off of each?",
      "Typical numbers, and why does overlap exist at all?",
      "How do you know your chunking is wrong?"],
  a:[{q:"Three approaches",t:"Fixed size — cut every N tokens. Simple, predictable, splits a thought in half. Semantic or structural — cut on headings, paragraphs, code blocks. Respects meaning, but chunks come out uneven, and a big paragraph may not fit. Sliding window — fixed size with overlap so boundary context isn't lost. In practice I go structural first, a size cap on top, and overlap as insurance. One approach in pure form is almost never the best one."},
     {q:"Numbers",t:"Two to five hundred tokens per chunk, about fifty tokens of overlap, or ten to fifteen percent. Overlap exists because a fact near a boundary would otherwise be split across two chunks, and neither would embed in a way that finds it. Bigger chunks give more context per hit, but the embedding averages the meaning and gets muddier. Smaller is more precise but fragmentary, and the answer lacks surroundings. And every chunk carries metadata — source, section, position — or you can't cite it."},
     {q:"Diagnosis",t:"Two symptoms. The retrieved chunk is relevant but the answer is incomplete — chunk too small, or cut in the wrong place. The retrieved chunks are vaguely similar but not the right ones — too big, meaning diluted. I check with an eval, not by reading: on a golden question set, does the gold passage land in the top-k? That isolates chunking and retrieval from generation. Change the size, run again, compare. In my RAG project chunk size was a knob I turned against a metric, not a feeling."}],
  kill:"Quoting one magic number and stopping. And <b>\"chunking is a detail\"</b> — it's the most common cause of bad RAG, and the interviewer knows it."}},

{n:17,tag:"Core-40 #29",sec:"rag",core:[29],
 ru:{topic:"Embeddings",
  qs:["Что такое эмбеддинг и что означает расстояние между двумя?",
      "Cosine против dot product. Размерности. Где хранить.",
      "Два случая, где семантический поиск промахивается, и что ты добавляешь."],
  a:[{q:"Что это",t:"Вектор из тысячи с лишним чисел, который энкодер строит так, чтобы тексты со схожим смыслом оказались рядом. Расстояние — это близость смысла, как её выучила модель на своих данных, а не абсолютная истина. Ключевое правило: запрос и документы эмбеддятся одной и той же моделью. Смешал модели — расстояния не значат ничего, и это тихая ошибка, которую находят через неделю."},
     {q:"Метрики",t:"Cosine смотрит только на угол между векторами, игнорируя длину. Dot product учитывает и длину. Если векторы нормализованы до единичной длины — а большинство провайдеров возвращают именно такие, — это одно и то же, и dot product просто дешевле. Размерности: полторы тысячи у OpenAI, тысяча двадцать четыре у Voyage. Больше измерений — тоньше различия, но дороже хранить и медленнее искать; некоторые модели позволяют усекать вектор. Храню в Postgres с pgvector и индексом HNSW — на моём масштабе отдельная векторная база не нужна."},
     {q:"Промахи",t:"Первый — точные идентификаторы: артикулы, имена, коды ошибок. Семантика их не различает, «ошибка 4017» и «ошибка 4071» рядом. Лечится гибридом с BM25, обычным лексическим поиском, и слиянием результатов. Второй — доменный сдвиг: модель училась на общем вебе, а у меня юридические или медицинские тексты, и расстояния теряют смысл. Лечится доменной моделью или реранкером, который читает пары внимательно. И ещё нюанс: запрос и документ — тексты разной природы, у некоторых моделей для них разные режимы."}],
  kill:"<b>«Эмбеддинги понимают смысл»</b> без слов «относительно данных обучения». И путать cosine с dot product, когда векторы нормализованы — это одно и то же."},
 en:{topic:"Embeddings",
  qs:["What is an embedding, and what does the distance between two mean?",
      "Cosine versus dot product. Dimensions. Where do you store them?",
      "Two cases where semantic search misses, and what you add."],
  a:[{q:"What it is",t:"A vector of a thousand-odd numbers that an encoder produces so that texts with similar meaning land close together. Distance is semantic closeness as the model learned it from its training data, not absolute truth. The key rule: the query and the documents are embedded with the same model. Mix models and the distances mean nothing — a silent bug that gets found a week later."},
     {q:"Metrics",t:"Cosine looks only at the angle between vectors and ignores length. Dot product includes length. If the vectors are normalised to unit length — and most providers return them that way — the two are identical, and dot product is simply cheaper. Dimensions: fifteen hundred-odd for OpenAI, ten twenty-four for Voyage. More dimensions, finer distinctions, but more storage and slower search; some models let you truncate the vector. I store in Postgres with pgvector and an HNSW index — at my scale a separate vector database isn't justified."},
     {q:"Misses",t:"First — exact identifiers: part numbers, names, error codes. Semantics doesn't separate them; error 4017 and error 4071 sit side by side. The fix is hybrid search with BM25, plain lexical matching, and merging the two result lists. Second — domain shift: the model was trained on the general web and my documents are legal or medical, so distances lose meaning. The fix is a domain model or a reranker that reads the pairs carefully. One more nuance: a query and a document are different kinds of text, and some models have separate modes for each."}],
  kill:"<b>\"Embeddings understand meaning\"</b> without adding \"relative to their training data\". And confusing cosine with dot product when the vectors are normalised — they're the same thing."}},

{n:18,tag:"Core-40 #30",sec:"rag",core:[30],
 ru:{topic:"Top-k и reranking",
  qs:["Что такое k и как ты его выбираешь?",
      "Что делает реранкер и почему он второй стадией, а не первой?",
      "Цена и задержка реранкинга. Когда его пропускаешь?"],
  a:[{q:"k",t:"k — сколько кандидатов я вытаскиваю из векторного индекса, обычно от пяти до двадцати. Слишком мало — нужный пассаж не попадает вообще. Слишком много — в контекст идёт шум, растёт цена, и модель теряет нужное посередине. Выбираю не по интуиции, а по recall at k на золотом наборе: наименьшее k, при котором нужный пассаж почти всегда внутри. Это одна из самых дешёвых метрик во всём пайплайне, она детерминирована и не требует LLM-судьи."},
     {q:"Реранкер",t:"Первая стадия — embedding search — быстрая и приближённая: запрос и документ кодируются по отдельности и никак не взаимодействуют. Реранкер — это cross-encoder: он читает запрос и каждого кандидата вместе и оценивает релевантность точно. Прогнать его по всему корпусу нельзя, слишком дорого. По двадцати кандидатам — легко. Поэтому схема: достать двадцать, переранжировать, оставить три–пять. Cohere или Voyage по API, либо локальный cross-encoder. У меня в пайплайне он стоит после retrieval, и это была одна из ручек, которые я крутил по эвалу."},
     {q:"Цена",t:"Это ещё один сетевой вызов, обычно сто–триста миллисекунд, и оплата за каждый документ. Пропускаю, когда корпус крошечный, когда k и так маленькое, или когда бюджет задержки жёсткий. Добавляю, когда точность важнее — ответы цитируют не тот документ — или когда корпус большой и грязный. Решение измеряю: precision в top-3 с реранкером и без. Если разницы нет, лишний вызов не нужен."}],
  kill:"<b>«Реранкинг — просто ещё раз отсортировать по score»</b> — нет, это другая модель, которая читает пары. И <b>k равно одному</b> — тогда любой промах ретривера фатален."},
 en:{topic:"Top-k and reranking",
  qs:["What is k, and how do you choose it?",
      "What does a reranker do, and why is it a second stage rather than the first?",
      "Cost and latency of reranking. When do you skip it?"],
  a:[{q:"k",t:"k is how many candidates I pull from the vector index, usually five to twenty. Too few and the right passage doesn't show up at all. Too many and the context fills with noise, cost rises, and the model loses the relevant bit in the middle. I choose it by recall at k on a golden set, not intuition: the smallest k where the gold passage is almost always inside. It's one of the cheapest metrics in the whole pipeline — deterministic, no LLM judge needed."},
     {q:"Reranker",t:"The first stage — embedding search — is fast and approximate: query and document are encoded separately and never interact. A reranker is a cross-encoder: it reads the query and each candidate together and scores relevance precisely. You can't run it over the whole corpus, far too expensive. Over twenty candidates, easily. So the pattern is: retrieve twenty, rerank, keep three to five. Cohere or Voyage over an API, or a local cross-encoder. In my pipeline it sits after retrieval, and it was one of the knobs I tuned against the eval."},
     {q:"Cost",t:"It's another network call, typically a hundred to three hundred milliseconds, billed per document. I skip it when the corpus is tiny, when k is small anyway, or when the latency budget is tight. I add it when precision matters more — answers citing the wrong document — or when the corpus is large and noisy. I measure the decision: precision at three with and without the reranker. No difference, no extra call."}],
  kill:"<b>\"Reranking is just sorting by score again\"</b> — no, it's a different model that reads the pairs. And <b>k equals one</b> — then any retriever miss is fatal."}},

{n:19,tag:"Core-40 #31",sec:"rag",core:[31],
 ru:{topic:"RAG: где ломается и как мерить",
  qs:["Четыре места, где RAG ломается. По стадиям.",
      "Метрики: faithfulness, relevance, recall. Определи и скажи, как мерить каждую.",
      "Как ты построил эвал для своего RAG? Что именно в наборе?"],
  a:[{q:"Четыре места",t:"Ингестия: плохой парсинг PDF или неверный chunking, и знание вообще не попало в индекс как надо. Retrieval miss: нужный пассаж не в top-k, потому что запрос сформулирован иначе или эмбеддинг не различает. Ранжирование: пассаж есть, но закопан на пятнадцатом месте и в контекст не попал. Генерация: модель игнорирует контекст, отвечает из головы или добавляет то, чего в контексте нет. Главный принцип — диагностировать по стадиям, а не смотреть на итоговый ответ: иначе непонятно, что чинить."},
     {q:"Метрики",t:"Recall, или hit rate: попал ли нужный пассаж в выборку. Нужен размеченный набор, зато считается детерминированно и мгновенно. Context relevance, или precision: какая доля вытащенных кусков вообще относится к делу. Faithfulness, или groundedness: каждое утверждение в ответе подтверждается вытащенным контекстом — мерю LLM-судьёй со строгой рубрикой или проверкой цитат. Answer relevance: ответ отвечает на вопрос, а не на соседний. Ключевое — разделять метрики retrieval и метрики генерации: первые дешёвые и точные, вторые дорогие и шумные."},
     {q:"Мой эвал",t:"Золотой набор: вопросы, к каждому — ожидаемый исходный пассаж и факты, которые должны быть в ответе. Прогоняю пайплайн, recall at k считаю автоматически. Для faithfulness — LLM-судья с рубрикой, и выборочно проверяю судью руками, потому что судья тоже ошибается. Гоняю на каждый коммит, чтобы смена размера куска отражалась числом, а не впечатлением. Набор небольшой, и это нормально: тридцать–пятьдесят хороших вопросов лучше, чем ноль. Именно поэтому я могу сказать, что пайплайн работает, а не утверждать это."}],
  kill:"<b>«Работает, я потыкал пару вопросов»</b>. И мерить только end-to-end: ответ плохой, а какая из четырёх стадий виновата — неизвестно."},
 en:{topic:"RAG: where it breaks and how to measure",
  qs:["Four places RAG breaks. By stage.",
      "Metrics: faithfulness, relevance, recall. Define each and say how you measure it.",
      "How did you build the eval for your RAG? What exactly is in the set?"],
  a:[{q:"Four places",t:"Ingestion: bad PDF parsing or wrong chunking, so the knowledge never made it into the index properly. Retrieval miss: the right passage isn't in the top-k, because the query is phrased differently or the embedding doesn't separate them. Ranking: the passage is there but buried at position fifteen and never reaches the context. Generation: the model ignores the context, answers from memory, or adds things the context doesn't say. The principle is to diagnose by stage, not by looking at the final answer — otherwise you don't know what to fix."},
     {q:"Metrics",t:"Recall, or hit rate: did the gold passage make it into the retrieved set. Needs a labelled set, but it's deterministic and instant. Context relevance, or precision: what fraction of retrieved chunks are actually on-topic. Faithfulness, or groundedness: every claim in the answer is supported by retrieved context — measured with an LLM judge on a strict rubric, or citation checks. Answer relevance: it answers the question asked, not a neighbouring one. The key is separating retrieval metrics from generation metrics — the first are cheap and exact, the second expensive and noisy."},
     {q:"My eval",t:"A golden set: questions, and for each one the expected source passage and the facts the answer must contain. I run the pipeline and compute recall at k automatically. For faithfulness, an LLM judge with a rubric, and I spot-check the judge by hand because judges are wrong too. It runs on every commit, so a chunk-size change shows up as a number rather than an impression. The set is small, and that's fine: thirty to fifty good questions beat zero. It's the reason I can say the pipeline works instead of claiming it."}],
  kill:"<b>\"It works, I tried a few questions.\"</b> And measuring only end-to-end: the answer is bad and which of the four stages is at fault stays unknown."}}

,
{n:20,tag:"Core-40 #35 · system design",sec:"sysd",core:[35],
 ru:{topic:"Дизайн: streaming chat UI",
  qs:["Спроектируй стриминговый чат. Компоненты от браузера до модели, по порядку.",
      "Состояние на клиенте: что хранишь, как рендеришь частичный ответ, где живёт история.",
      "UX отказов: retry, cancel, ошибка посреди потока. И что ты логируешь."],
  a:[{q:"Компоненты",t:"Браузер никогда не ходит в модель напрямую — ключ утечёт, и контроля нет. Браузер ходит в мой API route. Сервер принимает новое сообщение пользователя и id разговора, сам восстанавливает историю из базы, добавляет system prompt, вызывает провайдера со stream: true и проксирует SSE клиенту. По завершении сохраняет ответ ассистента вместе с usage. Клиент делает fetch с POST, читает ReadableStream, дописывает дельты. Историю клиент не присылает: доверять клиентской истории нельзя ни по цене, ни по безопасности — её подменят."},
     {q:"Состояние",t:"Массив сообщений, у каждого статус: pending, streaming, done, error. Частичный текст дописываю в контент стримящегося сообщения, рендер батчу через requestAnimationFrame, а не на каждый токен. Markdown рендерю инкрементально, с оговоркой: незакрытый блок кода посреди потока ломает разметку, это надо обрабатывать. Сообщение пользователя показываю оптимистично сразу. Автоскролл вниз — только если пользователь сам не проскроллил вверх. Стоимость и токены на сообщение — из usage в конце. Обрезка длинной истории — на сервере: скользящее окно или саммари, клиент об этом не знает."},
     {q:"Отказы",t:"Стоп — через AbortController, и сервер тоже прерывает вызов к провайдеру, чтобы не платить за то, что уже никто не читает. Обрыв — частичный текст остаётся на экране с пометкой, retry шлёт тот же id, чтобы сервер не задублировал сообщение. Ошибки различаю: 429 — backoff и повтор, перегрузка провайдера — повтор, слишком длинный запрос — честно сказать пользователю. Логирую request id, время до первого токена, общее время, stop_reason, usage и модель. Именно по этим полям потом разбираешь «почему тормозит»."}],
  kill:"<b>Ключ API в браузере</b> — дисквалификация. И <b>перерендер всего markdown на каждый токен</b> — чат начнёт лагать на длинных ответах, и это увидят на демо."},
 en:{topic:"Design: streaming chat UI",
  qs:["Design a streaming chat. Components from the browser to the model, in order.",
      "Client state: what you store, how you render partial output, where history lives.",
      "Failure UX: retry, cancel, an error mid-stream. And what you log."],
  a:[{q:"Components",t:"The browser never talks to the model directly — the key leaks and you have no control. The browser calls my API route. The server takes the new user message and a conversation id, rebuilds the history from the database itself, adds the system prompt, calls the provider with stream: true, and proxies the SSE to the client. On completion it persists the assistant message along with usage. The client does a POST fetch, reads the ReadableStream, appends deltas. The client never sends history: you can't trust client-supplied history for cost or for safety — it'll get tampered with."},
     {q:"State",t:"An array of messages, each with a status: pending, streaming, done, error. Partial text appends to the streaming message's content, and I batch renders on requestAnimationFrame rather than per token. Markdown renders incrementally, with one caveat: an unclosed code fence mid-stream breaks the layout, so that needs handling. The user's message shows optimistically right away. Auto-scroll to the bottom only if the user hasn't scrolled up. Cost and tokens per message come from usage at the end. Trimming a long history happens on the server — sliding window or summary — and the client doesn't know about it."},
     {q:"Failures",t:"Stop goes through an AbortController, and the server also aborts the provider call so nobody pays for output no one is reading. On a drop, the partial text stays on screen with a marker, and retry sends the same id so the server doesn't duplicate the message. I distinguish errors: 429 means back off and retry, provider overload means retry, request too long means tell the user honestly. I log request id, time to first token, total time, stop_reason, usage and model. Those are the fields you use later to answer why it feels slow."}],
  kill:"<b>API key in the browser</b> — disqualifying. And <b>re-rendering all the markdown on every token</b> — the chat starts to lag on long answers, and it shows during the demo."}},

{n:21,tag:"Core-40 #36 · system design",sec:"sysd",core:[36],
 ru:{topic:"Дизайн: RAG end-to-end",
  qs:["Пройди пайплайн от загрузки документа до ответа. Каждая стадия и выбор на ней.",
      "Хранение и индекс: pgvector или отдельная база? Метаданные, обновления, удаления.",
      "Обслуживание запросов: бюджет задержки, кэш, цитаты, права доступа, мониторинг."],
  a:[{q:"Пайплайн",t:"Загрузка, потом парсинг — PDF и HTML в текст, и это недооценённая стадия: таблицы и вёрстка ломаются чаще всего. Chunking с учётом структуры, двести–пятьсот токенов, с перекрытием. Эмбеддинг одной моделью, батчами. Хранение: текст куска, метаданные и вектор. На запросе: эмбеддю вопрос, достаю top-20, опционально гибрид с BM25, реранкер до пяти, собираю промпт с пронумерованными кусками и инструкцией отвечать только из контекста и ставить ссылки на номера. Генерирую, проверяю цитаты постобработкой, отдаю ответ вместе с источниками."},
     {q:"Хранение",t:"pgvector — когда Postgres уже есть и векторов меньше нескольких миллионов: одна база, транзакции, и права доступа через обычный join. Отдельная векторная база — на масштабе или когда нужна продвинутая фильтрация и скорость. Метаданные обязательны: id документа, тенант или пользователь, раздел, версия, время. Обновление документа — перечанкить его и удалить старые куски по id документа; поле версии спасает от устаревших кусков, которые иначе живут вечно. Ингестия должна быть идемпотентной: повторная загрузка не плодит дубли."},
     {q:"Обслуживание",t:"Бюджет: эмбеддинг запроса десятки миллисекунд, поиск по индексу столько же, реранкер сто–триста, генерация одна–три секунды, и она стримится. Кэширую эмбеддинги запросов, а для повторяющихся вопросов — и ответы, это семантический кэш. Фильтр по тенанту — до поиска по похожести, а не после: иначе пользователь достанет чужой документ. Цитаты принудительные: каждое утверждение привязано к id куска, неподтверждённые выбрасываются. Мониторю recall на золотом наборе, faithfulness, перцентили задержки, стоимость ответа и долю «релевантного контекста не найдено». Кнопки оценки ответа кормят золотой набор."}],
  kill:"Забыть парсинг и права доступа. И описать только счастливый путь — интервьюер спросит «как узнаете, что стало хуже?», и без эвала ответа нет."},
 en:{topic:"Design: RAG end-to-end",
  qs:["Walk the pipeline from document upload to answer. Every stage and the choice at it.",
      "Storage and indexing: pgvector or a dedicated store? Metadata, updates, deletes.",
      "Serving: latency budget, caching, citations, permissions, monitoring."],
  a:[{q:"Pipeline",t:"Upload, then parsing — PDF and HTML to text, and it's the underrated stage: tables and layout break most often. Structure-aware chunking, two to five hundred tokens, with overlap. Embedding with one model, in batches. Storage: chunk text, metadata and the vector. At query time: embed the question, pull the top twenty, optionally hybrid with BM25, rerank down to five, build the prompt with numbered chunks and an instruction to answer only from context and cite by number. Generate, verify the citations in post-processing, return the answer with its sources."},
     {q:"Storage",t:"pgvector when Postgres already exists and there are fewer than a few million vectors: one database, transactions, and permissions through an ordinary join. A dedicated vector store at scale, or when you need advanced filtering and speed. Metadata is mandatory: document id, tenant or user, section, version, timestamp. Updating a document means re-chunking it and deleting the old chunks by document id; a version field saves you from stale chunks that otherwise live forever. Ingestion has to be idempotent: uploading twice doesn't create duplicates."},
     {q:"Serving",t:"Budget: query embedding tens of milliseconds, index search about the same, reranker a hundred to three hundred, generation one to three seconds, streamed. I cache query embeddings, and for recurring questions the answers too — a semantic cache. Tenant filtering happens before the similarity search, not after: otherwise a user retrieves someone else's document. Citations are enforced: every claim maps to a chunk id, unsupported ones get dropped. I monitor recall on the golden set, faithfulness, latency percentiles, cost per answer, and the rate of no relevant context found. Thumbs-up and down feed the golden set."}],
  kill:"Forgetting parsing and permissions. And describing only the happy path — the interviewer will ask how you'd know it got worse, and without an eval there's no answer."}},

{n:22,tag:"Core-40 #37 · system design",sec:"sysd",core:[37],
 ru:{topic:"Дизайн: экономика LLM-продукта",
  qs:["Счёт вырос в три раза за месяц. Как находишь, где?",
      "Лестница рычагов, от самого дешёвого к сложному.",
      "Что кэширование не чинит? Пример из своего кода."],
  a:[{q:"Поиск",t:"Сначала измеряю, потом трогаю. Инструментирую каждый вызов: модель, input, output и cache-токены, фича, пользователь. Группирую по фиче и модели — почти всегда доминирует один шаг. Смотрю структуру: output в три–пять раз дороже за токен, но в агентах обычно доминирует input из-за пересылки истории. Ищу типовые причины: цикл без потолка, растущая история, многословные ответы, дорогая модель на массовом шаге. Пока нет разбивки по шагам, любое «давайте оптимизируем» — это гадание."},
     {q:"Лестница",t:"Роутинг моделей — самый большой рычаг, до десяти раз на массовых шагах. Prompt caching на статичном префиксе: запись дороже, чтение — около десятой части цены. Короче выходы: max_tokens, сжатый формат, структура вместо прозы. Сжатие входов: дешёвая модель пересказывает страницы до того, как их прочитает дорогая. Обрезка истории — окно или саммари. Batch API — половина цены, если результат не нужен сразу. Семантический кэш для повторных вопросов. Prompt compression — в последнюю очередь, это уже тонкая настройка. Порядок — по соотношению усилия к эффекту."},
     {q:"Не чинит",t:"Кэширование чинит пересылку, а не объём. Если в модель летит двадцать тысяч символов сырого HTML, кэш делает дешёвой вторую отправку, но первая и каждая новая страница стоят полную цену. У меня так и вышло: после включения кэша он дал полтора раза, и при этом cache writes стали шестьюдесятью процентами счёта. Следующий шаг был не кэш, а роутинг: дешёвая модель ужимает страницы до того, как их видит дорогая. И ещё: кэшу нужен стабильный префикс — timestamp в начале system prompt ломает его полностью, и это видно только по цифрам."}],
  kill:"<b>«Возьмите модель подешевле»</b> как весь ответ, без измерений. И утверждать, что <b>кэш решает всё</b> — интервьюер спросит про первую отправку."},
 en:{topic:"Design: LLM product economics",
  qs:["The bill tripled this month. How do you find where?",
      "The ladder of levers, cheapest to most complex.",
      "What can't caching fix? An example from your own code."],
  a:[{q:"Finding it",t:"Measure first, touch second. I instrument every call: model, input, output and cache tokens, feature, user. Group by feature and model — one step almost always dominates. Look at the structure: output is three to five times more expensive per token, but in agents input usually dominates because of history resends. Then the usual suspects: a loop with no cap, a growing history, verbose outputs, an expensive model on a bulk step. Without a per-step breakdown, any let's-optimise is guessing."},
     {q:"The ladder",t:"Model routing — the biggest lever, up to ten times on bulk steps. Prompt caching on the static prefix: writes cost more, reads are about a tenth of the price. Shorter outputs: max_tokens, a terse format, structure instead of prose. Input distillation: a cheap model summarises pages before the expensive one reads them. History trimming — window or summary. The batch API — half price when the result isn't needed immediately. A semantic cache for repeated questions. Prompt compression last; that's fine-tuning. The order is effort against impact."},
     {q:"Can't fix",t:"Caching fixes resending, not volume. If twenty thousand characters of raw HTML go into the model, the cache makes the second send cheap, but the first send and every new page still cost full price. That's exactly what happened to me: turning on caching gave one and a half times, and cache writes became sixty percent of the bill. The next step wasn't more caching, it was routing — a cheap model shrinks the pages before the expensive one sees them. One more: caching needs a stable prefix. A timestamp at the top of the system prompt breaks it entirely, and you only see it in the numbers."}],
  kill:"<b>\"Use a cheaper model\"</b> as the whole answer, with no measurement. And claiming <b>caching solves everything</b> — the interviewer will ask about the first send."}}

,
{n:23,tag:"Core-40 #38 · behavioral",sec:"behav",core:[38],
 ru:{topic:"Tell me about yourself",
  qs:["Версия на 60–90 секунд. Скажи её целиком.",
      "Версия на 30 секунд для рекрутера.",
      "Чего ты никогда не говоришь и чем заканчиваешь?"],
  a:[{q:"90 секунд",t:"Это не биография, а три абзаца с одной мыслью каждый. Первый: кто ты сейчас — senior frontend, десять лет, продуктовые интерфейсы, одна конкретная вещь с текущего места: миграция на App Router и интернационализация на пятьдесят с лишним стран. Второй: что ты строишь последний год — RAG-пайплайн с эвалом, который живёт на сайте, и research-агент на Anthropic SDK, который по имени компании собирает досье со ссылками. Третий: что ты ищешь — product engineer в маленьком AI-стартапе, где нужны и фронт, и AI с первого дня. Короткие предложения, настоящее время, у каждого утверждения — пруф."},
     {q:"30 секунд",t:"Та же структура, по одному предложению на абзац. Senior frontend, десять лет продуктовых интерфейсов. Последний год строю AI-продукты публично: RAG с эвалами на сайте, сейчас research-агент на Anthropic SDK. Ищу product engineer в AI-стартапе. Всё. Рекрутер услышал уровень, доказательство и куда тебя ставить — больше ему на этом этапе не нужно."},
     {q:"Запреты",t:"Никогда: «career switcher», «learning AI», «transitioning», «trying to get into». Это язык человека, который просит поверить на слово. Ты senior-инженер, который строит AI-продукты — это факт, у него есть ссылки. И заканчиваешь не хронологией, а запросом: какую роль ищешь и почему именно такую. Тогда интервьюер знает, что с тобой делать. Ответ без посадки — «…ну вот, как-то так» — стирает всё, что было до него."}],
  kill:"Хронология с 2016 года. И любое слово из списка «switcher / learning / transitioning» — после него весь остальной ответ слушают как оправдание."},
 en:{topic:"Tell me about yourself",
  qs:["The 60–90 second version. Say the whole thing.",
      "The 30-second version, for a recruiter.",
      "What do you never say, and how do you land it?"],
  a:[{q:"90 seconds",t:"I'm a senior frontend engineer with about ten years of experience — I've spent my career shipping product UIs. Right now I'm at Dats.Team, where I led a migration to the Next.js App Router and built internationalization for more than fifty countries. About a year ago I started building AI products in public. I shipped a full RAG pipeline — chunking, embeddings, retrieval, reranking — with an eval suite, and it's live on my site. Now I'm building a research agent in TypeScript on the Anthropic SDK: it takes a company name and produces a structured, fully-cited dossier. I'm looking for a product engineer role at a small AI startup — a place where my frontend depth and my AI engineering work are both useful from day one."},
     {q:"30 seconds",t:"Senior frontend engineer, ten years of shipping product UIs. For the last year I've been building AI products in public — a RAG pipeline with evals that's live on my site, and now a research agent on the Anthropic SDK. I'm looking for a product engineer role at an AI startup. That's it. The recruiter heard the level, the proof, and where to place you — nothing else is needed at this stage."},
     {q:"Never",t:"Never: career switcher, learning AI, transitioning, trying to get into. That's the language of someone asking to be taken on faith. You're a senior engineer who builds AI products — it's a fact, and it has links. And you land on the ask, not on chronology: which role you want and why that one. Then the interviewer knows what to do with you. An answer with no landing — so, yeah, that's me — erases everything before it."}],
  kill:"A chronology starting in 2016. And any word from the switcher / learning / transitioning list — after it, the rest of the answer is heard as an apology."}},

{n:24,tag:"Core-40 #39 · behavioral",sec:"behav",core:[39],
 ru:{topic:"История пивота",
  qs:["Почему из фронта в AI? Факты, не страсть.",
      "Это не шаг вниз по сеньорности?",
      "Что ты реально зашипил? Конкретно, с цифрами."],
  a:[{q:"Почему",t:"Ответ строится на наблюдении, а не на желании. Фронт десять лет назад: каждая задача новая, готовых паттернов нет. Фронт сегодня: сборка известного, и именно эту часть автоматизируют AI-инструменты. А работа с LLM сейчас выглядит как фронт в 2016: молодая экосистема, настоящие инженерные проблемы, никакого учебника. Поэтому ты не ждал, а начал шипить. Дальше — доказательства. Слово «passion» не произносится ни разу: за него не платят, за него не берут."},
     {q:"Не вниз?",t:"Нет, и вот почему. Title, который ты ищешь, — product engineer, а не junior AI something. В маленьких AI-компаниях фронтовая глубина — это senior-навык: у них продукт для разработчиков, и интерфейс — половина продукта. Ты не бросаешь десять лет, ты приносишь их в ту часть стека, где они сейчас нужнее всего. Плюс за год — не курсы, а рабочие системы с измерениями. Это горизонтальный шаг с расширением, а не спуск."},
     {q:"Зашипил",t:"Конкретика: RAG-пайплайн целиком — chunking, embeddings, retrieval, reranking — с эвал-набором, девять из девяти, живёт на сайте. Research-агент на TypeScript и Anthropic SDK: цикл с инструментами, каждое утверждение — со ссылкой на источник, инструментирована стоимость каждого шага. На нём я измерил prompt caching: полтора раза на одном прогоне, корректным A/B внутри запуска. Дальше роутинг: дешёвая модель ужимает страницы до дорогой. Всё открыто. Цифры — потому что интервьюер запомнит одно число, а не три прилагательных."}],
  kill:"<b>«Passion»</b>, <b>«всегда интересовался»</b>, туман вместо цифр. И извиняющаяся интонация — ты объясняешь решение, а не оправдываешься."},
 en:{topic:"The pivot story",
  qs:["Why move from frontend to AI? Facts, not passion.",
      "Isn't this a step down in seniority?",
      "What have you actually shipped? Be specific, with numbers."],
  a:[{q:"Why",t:"Honestly? I remember how frontend felt ten years ago — every problem was new, and I was building things that hadn't existed before. Today most frontend work is assembling known patterns, and AI tools are automating exactly that part. Meanwhile, building with LLMs feels like frontend felt in 2016: young ecosystem, real engineering problems, no established playbook. So I didn't wait — I started shipping. My RAG project is live with a nine-out-of-nine eval score, my research agent is in progress, everything is open source. I'm not running away from frontend — I'm bringing ten years of product engineering into the part of the stack where it matters most right now."},
     {q:"Not a step down",t:"No, and here's why. The title I'm going for is product engineer, not junior AI anything. At small AI companies frontend depth is a senior skill — the product is for developers, and the interface is half the product. I'm not throwing away ten years, I'm bringing them into the part of the stack that needs them most right now. And the last year wasn't courses, it was working systems with measurements. That's a lateral move with a wider scope, not a descent."},
     {q:"Shipped",t:"Specifics: a full RAG pipeline — chunking, embeddings, retrieval, reranking — with an eval set, nine out of nine, live on my site. A research agent in TypeScript on the Anthropic SDK: a tool-use loop, every claim carries a source URL, and the cost of every step is instrumented. On it I measured prompt caching — one and a half times on a single run, with a proper within-run A/B. Then routing: a cheap model shrinks pages before the expensive one reads them. All of it open. Numbers, because the interviewer will remember one number and not three adjectives."}],
  kill:"<b>Passion</b>, <b>always been interested</b>, fog instead of figures. And an apologetic tone — you're explaining a decision, not defending one."}},

{n:25,tag:"Core-40 #40 · behavioral",sec:"behav",core:[40],
 ru:{topic:"Три STAR-истории",
  qs:["Сложная техническая задача, которую ты решил. STAR, 90 секунд.",
      "Провал и что ты изменил навсегда. STAR, 90 секунд.",
      "Правила формы: как удержать любую историю в 90 секундах и чем она обязана заканчиваться?"],
  a:[{q:"Техническая",t:"История A, миграция. Ситуация: большое Next.js-приложение на Pages Router, нужен локализованный контент для пятидесяти с лишним стран. Задача: ты владел миграцией на App Router и всем слоем интернационализации. Действие: инкрементальная миграция, чтобы продукт продолжал шипиться — маршрут за маршрутом, next-intl для переводов, SWR для клиентского кэша, оптимизации сборки, чтобы пятьдесят локалей не взорвали build. Результат: мигрировали без заморозки фич, i18n обслуживает пятьдесят с лишним стран из одной кодовой базы. И мостик: инкрементальная миграция под живым трафиком — тот же навык, которым ты сейчас строишь AI-системы."},
     {q:"Провал",t:"История C — единственная, где ещё нет закреплённого факта, и это надо закрыть до первого скрина. Самый безопасный кандидат — перформанс-работа на Formind: что было сломано, что измерил, бандл минус двадцать пять процентов, загрузка плюс тридцать. Проверь цифры по своим записям. Структура провала строгая: что пошло не так и почему — не «случилось», а «я допустил». Что сделал немедленно. Что изменил навсегда, чтобы это не повторилось: процесс, проверка, метрика. Без третьей части это не история о провале, а история о везении."},
     {q:"Форма",t:"По одному–два предложения на каждую букву, не больше. Ситуация без предыстории компании — интервьюер не знает вашей оргструктуры и не хочет. «Я», а не «мы»: интервьюер оценивает тебя, а «мы» прячет твой вклад. В результате обязана быть цифра или наблюдаемый факт — иначе результат не отличить от намерения. Заканчиваешь предложением-посадкой: что это значит для роли, на которую ты претендуешь. Репетировать вслух, с таймером, пока не станет скучно. Скучно — значит готово."}],
  kill:"История без цифры в результате. И «мы сделали» вместо «я сделал» — интервьюер записывает: вклад неясен."},
 en:{topic:"Three STAR stories",
  qs:["A hard technical problem you solved. STAR, 90 seconds.",
      "A failure and what you changed permanently. STAR, 90 seconds.",
      "Rules of form: how do you keep any story to 90 seconds, and what must it end with?"],
  a:[{q:"Technical",t:"At Dats.Team we had a large Next.js app on the old Pages Router, and we needed to serve localized content for over fifty countries. I owned the migration to the App Router and the whole internationalization layer. I planned an incremental migration so the product kept shipping — route by route, with next-intl for translations, SWR for client caching, and build-time optimizations so fifty locales didn't explode our build. We migrated without freezing feature work, and the i18n system now serves fifty-plus countries from one codebase. The pattern I used — incremental migration under live traffic — is the same muscle I now use for AI systems: ship small, measure, keep moving."},
     {q:"Failure",t:"Story C is the one story without a locked fact yet, and it needs closing before the first screen. The safest candidate is the Formind performance work: what was broken, what I measured, bundle down twenty-five percent, load up thirty. Verify those numbers against your own notes. The failure structure is strict: what went wrong and why — not it happened but I let it happen. What I did immediately. What I changed permanently so it can't recur: a process, a check, a metric. Without the third part it isn't a failure story, it's a story about luck."},
     {q:"Form",t:"One or two sentences per letter, never more. Situation without company backstory — the interviewer doesn't know your org chart and doesn't want to. I, not we: they're evaluating you, and we hides your contribution. The result must contain a number or an observable fact — otherwise a result is indistinguishable from an intention. End on a landing sentence: what this means for the role you're interviewing for. Rehearse out loud with a timer until it's boring. Boring means ready."}],
  kill:"A story with no number in the result. And we did instead of I did — the interviewer writes down: contribution unclear."}}

,
{n:26,tag:"Core-40 #1–8 · parked check",sec:"parked",core:[1,2,3,4,5,6,7,8,42],
 ru:{topic:"JS/TS: проверка запаркованного",
  qs:["setTimeout(0) и Promise.resolve().then() — что раньше и почему? И почему forEach с await не ждёт?",
      "Классический баг closure с циклом и setTimeout до ES6. И четыре правила this плюс исключение для стрелок.",
      "Реализуй Pick<T, K> руками. Зачем discriminated union вместо optional-полей?"],
  a:[{q:"Event loop",t:"Микрозадачи всегда раньше макрозадач: после текущего синхронного кода движок опустошает очередь микрозадач целиком — промисы, queueMicrotask — и только потом берёт одну макрозадачу вроде setTimeout. Поэтому then выполнится первым даже при нуле. forEach с await не ждёт, потому что forEach не смотрит на возвращаемое значение колбэка: он получает промис и идёт дальше, все итерации стартуют параллельно. for...of работает внутри одной async-функции, и await там реально останавливает цикл."},
     {q:"Closure и this",t:"var в цикле — одна переменная на всю функцию, и к моменту срабатывания таймеров цикл уже закончился, все колбэки видят финальное значение. let создаёт привязку на итерацию, и каждая функция замыкает свою. this: по умолчанию — глобальный объект или undefined в strict; implicit — объект перед точкой; explicit — call, apply, bind; new — свежий объект. Стрелка не имеет своего this и берёт его лексически из окружения, поэтому её нельзя переопределить через call и нельзя использовать как метод, которому нужен this."},
     {q:"Типы",t:"type Pick<T, K extends keyof T> = { [P in K]: T[P] }: mapped type по ключам K, значение — индексный доступ. Discriminated union — Result равен либо { ok: true, data }, либо { ok: false, error }. Проверка ok сужает тип: в ветке true компилятор знает про data, в ветке false — про error, и невозможное состояние «и data, и error» не выражается вообще. С optional-полями каждый потребитель проверяет оба поля вручную и рано или поздно забывает. Из той же серии: Promise.all падает на первом реджекте, allSettled ждёт всех и отдаёт статусы."}],
  kill:"Ответить «then первый» без слова <b>микрозадача</b> — это угадывание. И описать стрелку как «короткий синтаксис» — интервьюер ждёт про this."},
 en:{topic:"JS/TS: parked check",
  qs:["setTimeout(0) versus Promise.resolve().then() — which runs first and why? And why doesn't forEach with await wait?",
      "The classic closure bug with a loop and setTimeout before ES6. And the four rules of this plus the arrow-function exception.",
      "Implement Pick<T, K> by hand. Why a discriminated union instead of optional fields?"],
  a:[{q:"Event loop",t:"Microtasks always run before macrotasks: after the current synchronous code, the engine drains the whole microtask queue — promises, queueMicrotask — and only then picks one macrotask like setTimeout. So then fires first even at zero. forEach with await doesn't wait because forEach ignores the callback's return value: it gets a promise and moves on, so every iteration starts in parallel. for...of runs inside a single async function, and await there genuinely pauses the loop."},
     {q:"Closure and this",t:"var in a loop is one variable for the whole function, and by the time the timers fire the loop is finished, so every callback sees the final value. let creates a binding per iteration, and each function closes over its own. this: default — the global object, or undefined in strict mode; implicit — the object before the dot; explicit — call, apply, bind; new — a fresh object. An arrow has no this of its own and takes it lexically from the surrounding scope, so you can't override it with call and can't use it as a method that needs this."},
     {q:"Types",t:"type Pick<T, K extends keyof T> = { [P in K]: T[P] } — a mapped type over the keys in K, with an indexed access for the value. A discriminated union: Result is either { ok: true, data } or { ok: false, error }. Checking ok narrows the type — in the true branch the compiler knows about data, in the false branch about error, and the impossible state of both data and error can't be expressed at all. With optional fields every consumer checks both by hand and eventually forgets. Same family: Promise.all rejects on the first rejection, allSettled waits for all and returns statuses."}],
  kill:"Saying then goes first without the word <b>microtask</b> — that's guessing. And describing an arrow function as short syntax — the interviewer is waiting for this."}},

{n:27,tag:"Core-40 #9–16 · parked check",sec:"parked",core:[9,10,11,12,13,14,15,16],
 ru:{topic:"React: проверка запаркованного",
  qs:["Почему хуки нельзя вызывать в условиях? Когда вызывается cleanup в useEffect? Что не так с объектом в массиве зависимостей?",
      "useMemo против useCallback — и когда они реально нужны. Почему key равный index ломается при reorder?",
      "RSC против SSR. Что делает Suspense при стриминге. Три вещи из React 19."],
  a:[{q:"Хуки",t:"React не знает имён хуков — он хранит их состояние в списке и сопоставляет по порядку вызова. Условие меняет порядок, и второй рендер читает чужое состояние. Cleanup вызывается перед следующим запуском того же эффекта и при размонтировании; не отписался — подписка живёт после смерти компонента, утечка и setState на размонтированном. Объект или массив в deps — на каждом рендере новая ссылка, эффект бежит каждый раз, и это выглядит как «бесконечный цикл»; либо стабилизировать через useMemo, либо класть в deps примитивы."},
     {q:"Мемоизация",t:"useMemo кэширует значение, useCallback — функцию; второе — это useMemo, возвращающий функцию. Реально нужны в двух случаях: дорогое вычисление, которое измерили, и стабильная ссылка, которую ждёт memo-дочерний компонент или массив deps. «Для производительности по умолчанию» — не аргумент: мемоизация сама стоит памяти и сравнений. key равный index: при перестановке элементов React видит те же ключи на тех же позициях, считает, что изменилось содержимое, и переиспользует состояние и DOM не тех элементов — поле ввода остаётся в старой строке. Ключ должен идентифицировать сущность."},
     {q:"RSC и 19",t:"SSR рендерит компонент на сервере в HTML, а потом всё равно отправляет его JS клиенту для гидрации. Server Component выполняется только на сервере, его код не попадает в бандл вообще, он может напрямую читать базу, но не может держать состояние и использовать хуки. Клиентский — там, где интерактивность. Suspense при стриминге позволяет отдать оболочку сразу, а медленные части досылать по мере готовности в том же потоке HTML. React 19: Actions — асинхронные функции для форм и переходов, useActionState для их состояния и ошибок, use — чтение промиса или контекста прямо в рендере."}],
  kill:"<b>«Хуки нельзя в условиях, потому что так написано в доке»</b> — нужно слово «порядок вызова». И «useMemo для производительности» без «измерил» — интервьюер спросит, что именно ты измерил."},
 en:{topic:"React: parked check",
  qs:["Why can't hooks be called conditionally? When does a useEffect cleanup run? What's wrong with an object in the dependency array?",
      "useMemo versus useCallback — and when are they actually needed. Why does key equal to index break on reorder?",
      "RSC versus SSR. What Suspense does with streaming. Three things from React 19."],
  a:[{q:"Hooks",t:"React doesn't know hook names — it stores their state in a list and matches by call order. A condition changes the order, and the next render reads someone else's state. Cleanup runs before the next run of the same effect and on unmount; skip it and the subscription outlives the component — a leak, and setState on an unmounted component. An object or array in deps is a new reference every render, so the effect runs every time and looks like an infinite loop; either stabilise it with useMemo or put primitives in deps."},
     {q:"Memoisation",t:"useMemo caches a value, useCallback caches a function — the second is just useMemo returning a function. They're genuinely needed in two cases: an expensive computation you've measured, and a stable reference that a memoised child or a deps array is waiting for. For performance by default isn't an argument — memoisation itself costs memory and comparisons. key equal to index: on reorder React sees the same keys at the same positions, assumes the content changed, and reuses the state and DOM of the wrong elements — the input stays in the old row. A key has to identify the entity."},
     {q:"RSC and 19",t:"SSR renders a component to HTML on the server and then still ships its JavaScript to the client for hydration. A Server Component runs only on the server, its code never enters the bundle, it can read the database directly, but it can't hold state or use hooks. Client components are where the interactivity is. Suspense with streaming lets you send the shell immediately and stream the slow parts as they're ready in the same HTML response. React 19: Actions — async functions for forms and transitions; useActionState for their state and errors; use — reading a promise or a context directly during render."}],
  kill:"<b>\"Hooks can't be conditional because the docs say so\"</b> — the phrase is call order. And useMemo for performance without I measured — the interviewer will ask what exactly you measured."}}

];

